from pathlib import Path
import json,re

root=Path(__file__).parent/'homework-1-Homework1'
source=json.loads((root/'source.json').read_text(encoding='utf-8'))
# Each entry supplies a problem-specific reading, literal first line and reason,
# error to avoid, and a fresh independent check for each original subpart.
D={
1:(r'숫자를 바꾸는 문제가 아니라 자리의 방향을 바꾸는 문제예요. 행을 열로 옮기고, 결과의 크기도 함께 적어요.',r'$(A^\top)_{ij}=A_{ji}$부터 써요. 전치(transpose)의 정의가 이 식이라, 원래 첫 행을 결과의 첫 열로 세우면 돼요. $2\times3\to3\times2$, $3\times1\to1\times3$을 먼저 표시해요.',r'전치는 원소를 정렬하거나 부호를 바꾸는 연산이 아니에요. 열벡터의 전치는 행벡터예요.',[r'답의 첫 열 $(1,-2,3)^\top$을 다시 첫 행으로 옮기면 원래 A가 나와요. $(A^\top)^\top=A$이며 모든 여섯 원소가 복원돼요.',r'$b^\top=(2,-1,4)$에 다시 전치를 하면 원래 $3\times1$ 벡터가 돼요. 원소 수는 3개 그대로예요.',r'$(C^\top)_{12}=-1=C_{21}$, $(C^\top)_{31}=0=C_{13}$이에요. 전체를 다시 전치해 원래 C의 아홉 원소를 확인해요.']),
2:(r'내적은 두 벡터를 같은 자리끼리 곱해 더한 하나의 수이고, 노름은 벡터의 길이예요. 마지막에는 내적으로 직교 여부를 판단해요.',r'$x^\top y=\sum_{i=1}^3x_i y_i$, $\|x\|_2=\sqrt{x^\top x}$부터 써요. 내적(dot product)은 $1\times3$과 $3\times1$의 곱이라 스칼라가 돼요.',r'$(-2)^2=4$예요. 길이의 제곱과 길이를 구별하고 마지막 제곱근을 잊지 않아요.',[r'독립적으로 $x^\top y=2-2+0=0$이에요. 또 $\|x+y\|^2=\|(3,-1,2)\|^2=14=9+5$라 교차항이 0인 것도 확인돼요.',r'$x^\top x=1+4+4=9$이고 양의 제곱근은 3이에요. $3^2=9$로 되돌려 확인해요.',r'$y^\top y=4+1=5$이므로 길이는 $\sqrt5$예요. 노름은 음수가 될 수 없어요.',r'두 벡터가 0이 아니므로 $\cos\alpha=(x^\top y)/(\|x\|\|y\|)=0$이에요. 따라서 각도는 $90^\circ$이고 직교해요.']),
3:(r'두 곱을 각각 계산해야 해요. 왼쪽 행렬의 행과 오른쪽 행렬의 열을 짝지으면 순서를 왜 보존해야 하는지 보일 거예요.',r'$(AB)_{ij}=\sum_{k=1}^3 A_{ik}B_{kj}$부터 써요. 예를 들어 $(AB)_{12}=1\cdot1+2\cdot1+3\cdot0=3$이에요. BA에서는 B의 행과 A의 열로 짝을 바꿔요.',r'행렬 곱(matrix product)은 같은 자리의 원소끼리 곱하는 연산이 아니에요. 두 행렬 모두 $3\times3$이어도 교환법칙은 보장되지 않아요.',[r'곱을 일반적인 행·열 내적으로 다시 계산하면 $AB=\begin{bmatrix}4&3&5\\10&9&11\\16&15&17\end{bmatrix}$, $BA=\begin{bmatrix}5&7&9\\11&13&15\\8&10&12\end{bmatrix}$예요. $(1,1)$ 원소가 $4\ne5$이므로 두 곱은 달라요.']),
4:(r'행렬식(determinant)은 행렬마다 하나의 수예요. 2×2, 대각행렬, 일반 3×3의 모양을 보고 계산법을 고르며 (d)는 두 방법 모두 써요.',r'$\det\begin{bmatrix}a&b\\c&d\end{bmatrix}=ad-bc$부터 써요. (c)는 대각 원소를 곱해요. (d)의 첫 행 전개 부호는 $+,-,+$이고, 각 원소의 행·열을 지운 2×2 소행렬식을 곱해요.',r'행렬식은 원소의 합이 아니에요. Sarrus 규칙은 3×3에만 그대로 적용하며, 첫 행 전개의 가운데 부호는 마이너스예요.',[r'행을 소거하면 $R_2\leftarrow R_2-\frac23R_1$ 뒤 대각은 $3,10/3$이에요. 행 더하기는 행렬식을 보존하므로 곱은 10이에요.',r'$R_2\leftarrow R_2-3R_1$ 뒤 대각은 $1,6$이에요. 곱 6은 공식 결과와 같아요.',r'대각 원소 $2,-1,3$의 곱은 -6이에요. 음수 대각이 하나라 부호도 음수예요.',r'열을 보면 $D_{:3}=2D_{:2}-D_{:1}$이에요. 열들이 종속이므로 행렬식은 0이에요. 첫 행 전개와 Sarrus의 $36-36=0$을 별도 성질로 확인했어요.']),
5:(r'역행렬(inverse)은 곱했을 때 단위행렬이 되는 행렬이에요. 먼저 존재 여부를 보고, 후보를 만든 뒤 곱해서 확인해요.',r'$M^{-1}=\frac1{ad-bc}\begin{bmatrix}d&-b\\-c&a\end{bmatrix}$, $ad-bc\ne0$부터 써요. 2×2에서 주대각을 맞바꾸고 비대각의 부호를 바꾸는 공식이에요. (c)는 두 좌표와 마지막 좌표가 섞이지 않는 블록대각 구조를 이용해요.',r'모든 원소를 역수로 바꾸면 역행렬이 되지 않아요. 분모의 행렬식과 음수 부호를 빠뜨리지 않아요.',[r'$\begin{bmatrix}1&-1\\-1&2\end{bmatrix}A=\begin{bmatrix}1&0\\0&1\end{bmatrix}$이에요. 풀이의 AX뿐 아니라 XA도 정확히 단위행렬이에요.',r'$\begin{bmatrix}1&2\\-3&1\end{bmatrix}B=\begin{bmatrix}7&0\\0&7\end{bmatrix}$이에요. 따라서 $1/7$을 곱한 후보는 양쪽 곱 모두 단위행렬이에요.',r'첫 블록은 $\frac13\begin{bmatrix}2&-1\\-1&2\end{bmatrix}\begin{bmatrix}2&1\\1&2\end{bmatrix}=I_2$이고 마지막 원소는 $(1/2)2=1$이에요. 블록 사이의 0도 그대로라 전체 양쪽 곱은 $I_3$예요.']),
6:(r'벡터 개수가 3이라는 이유만으로 독립이라고 할 수 없어요. 0을 만들 수 있는 계수 중 모두 0이 아닌 조합이 있는지 찾아요.',r'$c_1x_1+c_2x_2+c_3x_3=0$부터 써요. 선형 독립(linear independence)의 정의를 그대로 방정식으로 바꾼 거예요. 각 좌표가 0이어야 하므로 세 식을 얻어요.',r'$(0,0,0)$ 계수는 어떤 벡터에도 가능해서 종속의 근거가 아니에요. 적어도 하나가 0이 아닌 계수를 보여야 해요.',[r'$-2(2,-1,3)+(1,1,-2)+(3,-3,8)=(0,0,0)$이에요. 계수 $(-2,1,1)$이 비자명하므로 종속이라는 결론이 정의에 직접 부합해요.']),
7:(r'구할 것은 새로운 벡터가 아니라, 세 주어진 벡터를 얼마나씩 섞을지 정하는 세 계수예요.',r'$y=ax_1+bx_2+cx_3$부터 써요. 선형결합(linear combination)의 미지수는 $a,b,c$예요. 같은 좌표끼리 맞추면 세 연립방정식이 돼요.',r'계수는 음수도 가능해요. 한 좌표만 맞추고 끝내지 말고 세 좌표를 모두 확인해요.',[r'답 $(-6,3,2)$를 대입하면 첫 좌표 $-6+3+4=1$, 둘째 $-6+6-2=-2$, 셋째 $-6+9+2=5$예요. 열로 세운 계수행렬의 행렬식은 5로 0이 아니어서 계수도 유일해요.']),
8:(r'직사각형 A 자체의 역을 묻는 것이 아니라, 두 열 사이의 내적을 모은 2×2 행렬의 역을 물어요.',r'$A^\top A=\begin{bmatrix}a_1^\top a_1&a_1^\top a_2\\a_2^\top a_1&a_2^\top a_2\end{bmatrix}$부터 써요. $A:3\times2$, $A^\top:2\times3$이므로 결과는 $2\times2$예요.',r'$A^\top A$와 $AA^\top$는 크기부터 달라요. 대각의 역수 법칙은 비대각이 0인 대각행렬에 사용해요.',[r'$G=\operatorname{diag}(3,2)$, $\det G=6$, $G^{-1}=\operatorname{diag}(1/3,1/2)$예요. $GG^{-1}=G^{-1}G=I_2$이고, $v^\top Gv=3v_1^2+2v_2^2>0$은 영벡터 외에 성립해 역의 존재와도 맞아요.']),
9:(r'각 입력을 세 특징으로 바꾸고, 한 관측을 한 행에 담아요. 그 뒤 세 계수와 내적하면 예측값이 나와요.',r'$\Phi_{n:}=\phi(x_n)^\top=(1,x_n,x_n^2)$부터 써요. 특징행렬(feature matrix)은 관측 수×특징 수이며, 열벡터 특징을 전치해서 행으로 넣어요.',r'선형회귀의 선형성은 파라미터에 대한 것이에요. $x^2$가 있다는 이유만으로 선형회귀가 아니라고 판단하지 않아요.',[r'직접 다항식 $f(x)=1+x+2x^2$에 $-1,0,1$을 넣으면 $(2,1,4)^\top$이에요. 행렬곱 예측과 같아요. 고정된 x에 대해 $f_{a\theta+b\eta}(x)=af_\theta(x)+bf_\eta(x)$이므로 파라미터에 선형이에요.']),
10:(r'먼저 함수 전체의 편미분을 구하고, 지정된 점은 마지막에 넣어요. 각 편미분에서는 다른 변수를 상수로 다뤄요.',r'$\nabla f=(f_u,f_v)^\top$부터 써요. 예를 들어 $\partial_u(3v^2)=0$, $\partial_u(2uv)=2v$예요. (c)는 $s=u+2v-w-3$를 두고 $\nabla(s^2)=2s\nabla s$로 시작해요.',r'점의 값을 먼저 넣으면 상수 함수를 미분하게 돼요. (c)의 $w$ 미분은 $\partial_w s=-1$이고, 과제의 gradient는 열벡터예요.',[r'$f(1+t,-1)-f(1,-1)=t^2$이므로 u방향 일차계수는 0이에요. $f(1,-1+t)-f(1,-1)=-2t+3t^2$라 v방향은 -2예요.',r'$g(1+t,-1)-g(1,-1)=-4t+t^2$, $g(1,-1+t)-g(1,-1)=-2t+3t^2$예요. 일차계수는 $(-4,-2)^\top$이에요.',r'기준점에서 $s=-1$이에요. u,v,w만 각각 t만큼 옮겼을 때 h의 변화는 $-2t+t^2$, $-4t+4t^2$, $2t+t^2$예요. 일차계수는 $(-2,-4,2)^\top$이에요.']),
11:(r'출력이 여러 개일 때 각 출력의 편미분을 행으로 쌓은 것이 야코비안(Jacobian)이에요. 입력 2개는 두 열에 대응해요.',r'$J_{ij}=\partial f_i/\partial x_j$부터 써요. 첫 행은 첫 출력의 u,v 미분, 둘째 행은 둘째 출력의 미분이에요. (a)는 2×2, (b)는 3×2예요.',r'출력과 입력의 축을 뒤집지 않아요. 마지막 출력 $v^2$는 u와 무관하므로 그 행 첫 원소는 0이에요.',[r'입력을 $(\Delta u,\Delta v)=(a,b)$만큼 바꾸면 출력 변화는 정확히 $(a+2b,3a-b)^\top=J(a,b)^\top$이에요.',r'$(1,2)$에서 입력 변화 $(a,b)$에 대한 출력 변화는 $(2a+b+a^2,2a+b+ab,4b+b^2)^\top$이에요. 일차항만 모으면 표시한 $3\times2$ 야코비안의 곱이에요.']),
12:(r'행렬로 짧게 적힌 이차식을 두 변수 다항식으로 펼치고, 기울기가 0이 되는 점을 찾아요.',r'$Qx=(3x_1+x_2,x_1+2x_2)^\top$부터 써요. 왼쪽에서 $(x_1,x_2)$를 곱하면 교차항이 두 번 생기는 이유가 보여요.',r'교차항 $x_1x_2$가 두 번 있다는 것을 놓치지 않아요. $-2b^\top x=-2x_1+2x_2$의 둘째 부호도 확인해요.',[r'대칭행렬의 공식을 별도로 적용하면 $\nabla h=2Qx-2b=(6x_1+2x_2-2,2x_1+4x_2+2)^\top$예요. 직접 편미분과 같아요.',r'$Q(3/5,-4/5)^\top=(1,-1)^\top=b$예요. 또 $Q$의 첫 주축소행렬식은 3, 행렬식은 5로 양수라 헤시안 $2Q$는 양의 정부호예요. 구한 점은 유일한 전역 최소점이에요.']),
13:(r'가우시안 밀도에는 지수와 정규화 상수가 모두 필요해요. 먼저 평균만큼 중심을 옮긴 좌표를 쓰면 부호 오류가 줄어요.',r'$d=x-\mu=(x_1-1,x_2+1)^\top$부터 써요. 밀도는 $\exp(-d^\top\Sigma^{-1}d/2)/(2\pi\sqrt{\det\Sigma})$예요. 2차원이어서 분모의 $2\pi$는 제곱근이 아니에요.',r'지수에 들어가는 행렬은 공분산의 역인 정밀도(precision)예요. 평균의 둘째 성분이 -1이므로 중심좌표는 $x_2+1$이에요.',[r'중심 $(1,-1)$에서 전개된 괄호는 0이어서 최대밀도 $1/(2\pi\sqrt3)$이에요. 이동좌표에서 이차형식은 $\frac23(d_1^2-d_1d_2+d_2^2)$로 전개식과 항별 동일해요. 고윳값 3,1인 공분산이 양의 정부호이므로 가우시안 정규화 공식이 적용돼요.']),
14:(r'지수의 이차식을 완전제곱(completing the square)으로 바꾸면 중심과 폭을 읽을 수 있어요. 남는 상수는 밀도 앞에 반영해요.',r'$4z^2-8z+7=4(z-1)^2+3$부터 써요. 원래 식에 다시 펼쳐 맞는지 확인하고 $e^{-3/2}$를 상수로 꺼내요.',r'분산 v와 표준편차를 혼동하지 않아요. $e^{-3/2}$를 빠뜨리면 c가 틀려요.',[r'$\int_{-\infty}^{\infty}e^{-2(z-1)^2}dz=\sqrt{\pi/2}$이므로 전체 적분은 $c e^{-3/2}\sqrt{\pi/2}=1$이에요. 따라서 $c=\sqrt{2/\pi}e^{3/2}$, 평균 1, 분산 $1/4$이며 표준편차는 $1/2$예요.']),
15:(r'관측값은 고정하고, 파라미터를 바꿀 때 그 데이터가 얼마나 그럴듯한지 나타내는 우도(likelihood)를 구해요.',r'$r_n=y_n-\theta_0-\theta_1x_n$부터 써요. 잔차가 잡음이고 $r_n\sim N(0,\sigma^2)$라 한 관측의 밀도를 먼저 쓸 수 있어요. 독립성 때문에 전체 밀도는 곱이에요.',r'밀도의 합을 우도라고 쓰지 않아요. 독립 관측은 곱이고, 곱을 지수 하나로 모을 때만 제곱 잔차의 합이 돼요.',[r'$N=1$이면 한 가우시안의 밀도로 돌아가요. 일반 N에서 $(2\pi\sigma^2)^{-1/2}$를 N번 곱한 계수와 지수의 합이 정확히 $(2\pi\sigma^2)^{-N/2}\exp[-\sum r_n^2/(2\sigma^2)]$가 돼요. 이는 모든 양의 $\sigma^2$에서 성립하는 대수적 확인이에요.']),
16:(r'우도의 로그를 취하면 곱이 합으로 바뀌어서 계산하기 쉬워요. 음수를 붙이면 최대화 문제가 최소화 문제로 바뀌어요.',r'$r=y-\Phi\theta$, $\det(\sigma^2I_N)=(\sigma^2)^N$부터 써요. 전체 밀도의 정규화 상수를 알아야 음의 로그의 상수항도 빠짐없이 구할 수 있어요.',r'전체 음의 로그우도를 묻는 단계에서는 상수항을 지우지 않아요. 최적점만 비교할 때는 알려진 양의 분산이 파라미터와 무관하다는 조건을 사용해요.',[r'$\exp[-\{\frac N2\log(2\pi\sigma^2)+\frac1{2\sigma^2}\|r\|^2\}]$를 되돌리면 원 밀도예요. 임의의 두 파라미터 사이 목적함수 차이는 잔차제곱합 차이의 양수 $1/(2\sigma^2)$배라 순서와 최소점이 보존돼요.']),
17:(r'제곱오차가 가장 작아지는 계수를 먼저 일반식으로 구하고, 실제 세 데이터에 넣어요. 예측과 실제값의 차이도 끝까지 계산해요.',r'$J=(y-\Phi\theta)^\top(y-\Phi\theta)$부터 써요. 곱을 네 항으로 전개하면 미분할 때 무엇이 상수인지 보이고, 열벡터 gradient를 구할 수 있어요.',r'역행렬을 쓰기 전에 열의 선형 독립 조건을 확인해요. 잔차는 원 데이터와 예측의 차이이며, 최소제곱이어도 각 잔차가 0일 필요는 없어요.',[r'$v\ne0$에 대해 $v^\top\Phi^\top\Phi v=\|\Phi v\|^2>0$이에요. 따라서 헤시안은 양의 정부호예요. 정규방정식 해 $\theta_*$ 주위에서 $J(\theta_*+v)=J(\theta_*)+\|\Phi v\|^2$이므로 전역 최소성과 유일성도 확인돼요.',r'$\theta_*=(7/3,1)^\top$, $\hat y=(4/3,7/3,10/3)^\top$, $r=(2/3,-4/3,2/3)^\top$이에요. $\Phi^\top r=(0,0)^\top$로 잔차가 두 특징 열과 직교하며 $r^\top r=8/3$이에요.']),
18:(r'MAP은 데이터와 잘 맞는 정도에 사전분포의 선호를 더해 결정해요. 여기서는 절편을 포함한 모든 계수가 0에서 멀어질수록 벌점을 받아요.',r'$-\log p(\theta\mid\Phi,y)=-\log p(y\mid\Phi,\theta)-\log p(\theta)+C$부터 써요. 베이즈 규칙의 분모는 theta에 무관해서 C에 들어가요.',r'$b^2$는 사전 분산이에요. 잔차항 계수를 1로 맞춘 목적함수에서 $\lambda=\sigma^2/b^2$예요. 사전항만의 계수 $1/(2b^2)$와 동일시하지 않아요.',[r'$H=\Phi^\top\Phi+\lambda I$에 대해 $v^\top Hv=\|\Phi v\|^2+\lambda\|v\|^2>0$이에요. 열이 종속이어도 $\lambda>0$이면 역이 존재해요. $H\theta_*=\Phi^\top y$를 대입하면 gradient가 0이고 $J(\theta_*+v)-J(\theta_*)=v^\top Hv$라 유일 최소예요. $2\sigma^2$배 후 벌점계수가 $\sigma^2/b^2$인지도 확인해요.']),
19:(r'같은 데이터에 사전분포를 다르게 적용해 계수가 얼마나 줄어드는지 비교해요. 이 과제에서는 절편도 규제해요.',r'$\lambda=\sigma^2/b^2$, $(\Phi^\top\Phi+\lambda I)\theta=\Phi^\top y$부터 써요. 대각행렬이라 각 좌표의 식 $(3+\lambda)\theta_0=7$, $(2+\lambda)\theta_1=2$를 따로 풀면 돼요.',r'$b^2=1/4$이면 lambda는 1/4가 아니라 4예요. 절편을 규제에서 빼는 다른 관행을 이 문제에 적용하지 않아요.',[r'ML은 $(3,2)$에 각각 $(7/3,1)$을 곱하면 $(7,2)$예요. MAP은 $(4,3)$에 $(7/4,2/3)$을 곱하면 똑같이 $(7,2)$가 돼요.',r'$\lambda=4$일 때 $(7,6)$에 $(1,1/3)$을 곱하면 $(7,2)$예요. 두 좌표 모두 양수이고 분모가 증가하므로 0 쪽으로 수축해요.']),
20:(r'두 특징 열이 같아서 데이터만으로는 계수를 구분할 수 없어요. 규제를 붙이면 계수의 합뿐 아니라 각각의 크기도 제한해요.',r'$s=\theta_1+\theta_2$, $\Phi\theta=(s,2s)^\top$부터 써요. 이 데이터가 알려 주는 것은 합 s뿐이라는 사실이 바로 보여요. (c)의 벌점은 두 계수 각각에 적용돼요.',r'행렬식 0인 Gram 행렬의 역을 억지로 계산하지 않아요. (c)의 J에는 잔차와 벌점이 모두 포함돼요.',[r'각 열 내적은 5여서 Gram은 모든 원소가 5인 행렬이에요. 벡터 $(1,-1)^\top$을 곱하면 0이므로 특이행렬이라는 결론과 행렬식 0이 일치해요.',r'$(3,0)$과 $(1,2)$의 합은 둘 다 3이라 예측 $(3,6)^\top$과 제곱오차 0이 같아요. 실제로 $\theta_1+\theta_2=3$인 모든 계수가 같은 무규제 최소값을 내요.',r'$d=\theta_1-\theta_2$를 쓰면 $J=5(3-s)^2+\frac52(s^2+d^2)=\frac{15}{2}(s-2)^2+\frac52d^2+15$예요. 독립적인 완전제곱 검산으로 $s=2,d=0$, 즉 $(1,1)^\top$에서 최소값 15예요.']),
21:(r'각 좌표의 평균을 구한 뒤 평균에서 얼마나 떨어졌는지로 공분산을 계산해요. 이 문제는 분모 4를 명시해요.',r'$\bar x=\frac14\sum_n x_n$, $d_n=x_n-\bar x$부터 써요. 편차를 먼저 적으면 각 관측의 외적(outer product)을 한눈에 확인할 수 있어요.',r'$d_nd_n^\top$는 2×2 행렬이고 $d_n^\top d_n$는 수예요. 분모를 불편 추정에서 쓰는 3으로 바꾸지 않아요.',[r'편차 네 개의 합은 $(0,0)^\top$이에요. 평균 $(2,3)^\top$가 모든 관측의 중심인 것을 확인했어요.',r'별도로 $\frac14\sum x_nx_n^\top=\begin{bmatrix}5&7\\7&11\end{bmatrix}$이고 $\bar x\bar x^\top=\begin{bmatrix}4&6\\6&9\end{bmatrix}$예요. 차이는 $S=\begin{bmatrix}1&1\\1&2\end{bmatrix}$로 편차 외적 방식과 같아요.']),
22:(r'평균은 선형 변환하고, 공분산은 양쪽에서 행렬을 곱해요. (b)는 지수에서 역공분산을 읽어야 하고, (c)는 같은 잡음이 두 출력에 함께 들어가요.',r'$y=Ax+c$, $y-E[y]=A(x-E[x])$부터 써요. 중심화하면 상수 c가 사라져 $\Sigma_y=A\Sigma_xA^\top$, $C_{xy}=\Sigma_xA^\top$를 정의에서 얻어요. (c)는 여기에 $\varepsilon(1,1)^\top$를 더해요.',r'(b)의 교차항 계수는 정밀도 비대각 원소의 두 배예요. (c)의 $E[x_1x_2]=0$은 공분산 0이 아니며, 공유 잡음 공분산은 I가 아니라 모든 원소가 1인 행렬이에요.',[r'성분별 검산: $\mathrm{Var}(x_1+2x_2)=4+4\cdot2+4\cdot1=16$, $\mathrm{Var}(-x_1+x_2)=4+2-2=4$, 교차항 $-4+(1-2)\cdot1+2\cdot2=-1$이에요. 평균 $(6,-1)^\top$과 $C_{xy}=\begin{bmatrix}6&-3\\5&1\end{bmatrix}$도 각 입력과 출력의 공분산으로 다시 계산돼요.',r'정밀도 $P=\begin{bmatrix}1&-1\\-1&2\end{bmatrix}$와 $\Sigma_x=\begin{bmatrix}2&1\\1&1\end{bmatrix}$의 곱은 I예요. 성분별로 출력분산은 $4\cdot2+1-4=5$, $2+1+2=5$, 교차항은 $4+1-1=4$예요. 따라서 평균 $(2,2)^\top$, 공분산 $\begin{bmatrix}5&4\\4&5\end{bmatrix}$, 교차공분산 $\begin{bmatrix}3&3\\1&2\end{bmatrix}$예요.',r'$\mathrm{Cov}(x_1,x_2)=0-(1)(-1)=1$이에요. 출력분산은 $2+3+2+1=8$, $2+3-2+1=4$이고 두 출력의 공분산은 $2-3+1=0$이에요. 평균 $(0,2)^\top$이며 입력-잡음 독립성 때문에 $C_{xy}=\begin{bmatrix}3&1\\4&-2\end{bmatrix}$에 잡음 항은 없어요.']),
23:(r'절편이 없으므로 미지수는 기울기 하나예요. ML은 데이터만, MAP은 기울기가 0에 가깝다는 사전정보도 사용해요.',r'$r_1=2-\theta$, $r_2=3-2\theta$부터 써요. 두 독립 표준 가우시안 밀도를 곱한 뒤 음의 로그를 미분해요.',r'둘째 잔차를 미분하면 -2가 곱해져요. 예측은 학습에 쓰지 않은 입력 x=3에 구한 계수를 넣는 단계예요.',[r'곱의 상수는 $(2\pi)^{-1/2}(2\pi)^{-1/2}=1/(2\pi)$이고 지수는 $-[(2-\theta)^2+(3-2\theta)^2]/2$예요.',r'잔차제곱합을 별도로 전개하면 $5\theta^2-16\theta+13=5(\theta-8/5)^2+1/5$예요. 따라서 ML은 $8/5$, 최소 제곱오차는 $1/5$예요.',r'사전벌점까지 포함한 제곱식은 $6\theta^2-16\theta+13=6(\theta-4/3)^2+7/3$이에요. MAP은 $4/3$, 입력 3에서 예측은 ML $24/5$, MAP 4예요.']),
24:(r'여기서는 x 없이 세 관측 모두 같은 평균 theta를 공유해요. 사전분포가 선호하는 중심은 0이 아니라 1이에요.',r'$r_n=y_n-\theta$, $-\log p(\theta)=\frac12(\theta-1)^2+C$부터 써요. 사전 평균이 1이므로 제곱항의 중심도 1이어야 해요.',r'P23의 $\theta^2$ 벌점을 그대로 복사하지 않아요. 세 데이터의 평균과 사전 평균의 정밀도 가중 평균을 비교해요.',[r'독립 밀도 세 개의 곱은 $(2\pi)^{-3/2}\exp[-((2-\theta)^2+(3-\theta)^2+(4-\theta)^2)/2]$예요. 상수의 지수가 -3/2인지 확인해요.',r'제곱오차는 $3\theta^2-18\theta+29=3(\theta-3)^2+2$예요. 완전제곱으로 최소점 3을 확인해요.',r'사전 항을 더한 제곱식은 $4\theta^2-20\theta+30=4(\theta-5/2)^2+5$예요. 따라서 MAP은 $5/2=(3\cdot3+1\cdot1)/(3+1)$이고 사전 평균과의 거리 $3/2$가 ML의 거리 2보다 작아요.']),
25:(r'두 밀도가 동시에 높게 보는 위치를 찾는 문제예요. 곱 자체는 적분이 1일 필요가 없으므로, 정규화된 새 가우시안을 구해요.',r'$P_i=\Sigma_i^{-1}$, $\log(p_0p_1)=-\frac12\sum_{i=0}^1(x-\mu_i)^\top P_i(x-\mu_i)+C$부터 써요. 지수의 이차항과 일차항을 모아 완전제곱하면 평균과 공분산이 나와요.',r'공분산을 그냥 더하는 것은 독립 확률변수의 합에 쓰는 법칙이에요. 밀도의 곱에서는 정밀도를 더하고 마지막에 역을 취해요.',[r'$P_q\Sigma_q=I_2$, $P_q\mu_q=(1/3,1/3)^\top$를 정확한 분수로 확인했어요. 직접 전개한 원 지수와 중심화 지수의 차이는 $\frac5{22}$이라는 x와 무관한 상수예요. 원 곱의 적분은 $Z=\frac{1}{2\pi\sqrt{11}}e^{-5/22}$이며 $(p_0p_1)/Z$의 앞 계수는 $\frac1{2\pi}\sqrt{11/6}$예요. $\det\Sigma_q=6/11>0$이고 정밀도도 양의 정부호여서 이 밀도의 적분은 1이에요.'])
}

def paras(xs):return ''.join('<p>'+x+'</p>' for x in xs)
for p in source['problems']:
    n=p['number'];under,start,pit,ver=D[n];parts=p['subparts']
    grouped={s:[] for s in parts}
    common=[]
    for step in p['reference_steps']:
        m=re.match(r'^\(([a-z])\)',step)
        if parts==['main']: grouped['main'].append(step)
        elif m and m[1] in grouped: grouped[m[1]].append(step)
        else:common.append(step)
    # The worked arithmetic from the source is retained, with new entry reasoning,
    # method choice and independent verification, rather than silently replacing it.
    solve=paras(common)+''.join(f'<div data-subpart="{s}"><h4>{"풀이" if s=="main" else "("+s+")"}</h4>'+paras(grouped[s])+'</div>' for s in parts)
    verify=''.join(f'<div data-subpart="{s}"><h4>{"답을 확인해요" if s=="main" else "("+s+") 검산"}</h4><p>{v}</p></div>' for s,v in zip(parts,ver))
    assert len(parts)==len(ver)
    txt=f'''<div class="layer eli5" data-explanation="understand"><h4>무엇을 구하는 문제인가요?</h4><p>{under}</p></div>
<div class="layer formal" data-explanation="start"><h4>종이에 쓸 첫 줄</h4><p>{start}</p></div>
<div class="layer formal" data-explanation="solve"><h4>한 단계씩 계산해요</h4>{solve}<p><strong>완성 답</strong><br>{p['reference_answer']}</p></div>
<div class="layer formal" data-explanation="verify"><h4>다른 길로 검산해요</h4>{verify}</div>
<div class="layer warn" data-explanation="pitfall"><h4>이 부분을 조심해요</h4><p>{pit}</p></div>
<div class="layer eli5" data-explanation="retry"><h4>혼자 다시 풀어봐요</h4><ol><li>첫 줄의 식을 빈 종이에 쓰고 왜 이 식인지 말해요.</li><li>각 소문항의 계산을 답을 보지 않고 끝까지 진행해요.</li><li>검산 식으로 답과 조건이 맞는지 확인해요.</li></ol></div>
<div class="sum" hidden><p><strong>첫 줄</strong><br>{start}</p><p><strong>핵심 주의점</strong><br>{pit}</p><p><strong>답</strong><br>{p['reference_answer']}</p></div>'''
    (root/'explanations'/f"{p['id']}.html").write_text(txt,encoding='utf-8')
print('Authored 25 explanations,',sum(len(p['subparts']) for p in source['problems']),'subparts')
